pub(crate) fn expand_unicode_property_escape(body: &str, negated: bool) -> Option<String> {

    if !negated {
        if let Some(alt) = property_of_strings(body) {
            return Some(alt.to_string());
        }
    }
    let ranges = ranges_for(body)?;
    let mut s = String::with_capacity(ranges.len() * 12 + 3);
    s.push('[');
    if negated {
        s.push('^');
    }
    use std::fmt::Write;
    let mut emit = |s: &mut String, a: u32, b: u32| {
        if a == b {
            let _ = write!(s, "\\u{{{:X}}}", a);
        } else {
            let _ = write!(s, "\\u{{{:X}}}-\\u{{{:X}}}", a, b);
        }
    };

    let mut emitted = 0usize;
    for &(a, b) in ranges {
        if b < 0xD800 || a > 0xDFFF {
            emit(&mut s, a, b);
            emitted += 1;
        } else {
            if a < 0xD800 {
                emit(&mut s, a, 0xD7FF);
                emitted += 1;
            }
            if b > 0xDFFF {
                emit(&mut s, 0xE000, b);
                emitted += 1;
            }
        }
    }
    if emitted == 0 {

        return Some(if negated {
            "(?s:.)".to_string()
        } else {
            "(?!)".to_string()
        });
    }
    s.push(']');
    Some(s)
}

pub(crate) fn expand_unicode_property_escape_class_body(
    body: &str,
    negated: bool,
) -> Option<String> {
    if property_of_strings(body).is_some() {
        return None;
    }
    let ranges = ranges_for(body)?;

    let mut scalar: Vec<(u32, u32)> = Vec::new();
    for &(a, b) in ranges {
        if b < 0xD800 || a > 0xDFFF {
            scalar.push((a, b));
        } else {
            if a < 0xD800 {
                scalar.push((a, 0xD7FF));
            }
            if b > 0xDFFF {
                scalar.push((0xE000, b));
            }
        }
    }
    let effective = if negated {
        complement_scalar_ranges(&scalar)
    } else {
        scalar
    };
    if effective.is_empty() {
        return None;
    }
    use std::fmt::Write;
    let mut s = String::with_capacity(effective.len() * 12);
    for (a, b) in effective {
        if a == b {
            let _ = write!(s, "\\u{{{:X}}}", a);
        } else {
            let _ = write!(s, "\\u{{{:X}}}-\\u{{{:X}}}", a, b);
        }
    }
    Some(s)
}

fn complement_scalar_ranges(ranges: &[(u32, u32)]) -> Vec<(u32, u32)> {
    let mut out: Vec<(u32, u32)> = Vec::new();
    let push_gap = |out: &mut Vec<(u32, u32)>, lo: u32, hi: u32| {
        if hi < lo {
            return;
        }
        if hi < 0xD800 || lo > 0xDFFF {
            out.push((lo, hi));
        } else {
            if lo < 0xD800 {
                out.push((lo, 0xD7FF));
            }
            if hi > 0xDFFF {
                out.push((0xE000, hi));
            }
        }
    };
    let mut cursor: u32 = 0;
    for &(a, b) in ranges {
        if a > cursor {
            push_gap(&mut out, cursor, a - 1);
        }
        cursor = b.saturating_add(1);
    }
    if cursor <= 0x10FFFF {
        push_gap(&mut out, cursor, 0x10FFFF);
    }
    out
}

pub(crate) fn is_known_unicode_property_escape(body: &str) -> bool {
    ranges_for(body).is_some()
        || property_of_strings(body).is_some()
        || matches!(
            body,
            "Surrogate"
                | "Cs"
                | "gc=Surrogate"
                | "gc=Cs"
                | "General_Category=Surrogate"
                | "General_Category=Cs"
        )
}

